package dk.jamesbabz.madkursus.outbound.mealplan.details;
import java.time.Instant; import java.util.*; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="meal_plans") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class MealPlanEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private UUID userId; private String name; private Instant createdAt; private Instant updatedAt; @OneToMany(mappedBy="mealPlan",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("sortOrder") private List<PlannedRecipeEntity> recipes=new ArrayList<>(); public MealPlanEntity(UUID id,UUID userId,String name,Instant createdAt,Instant updatedAt){this.id=id;this.userId=userId;this.name=name;this.createdAt=createdAt;this.updatedAt=updatedAt;} public void update(String name,Instant updatedAt){this.name=name;this.updatedAt=updatedAt;} public void clearRecipes(){recipes.clear();} public void addRecipe(PlannedRecipeEntity r){recipes.add(r);r.setMealPlan(this);} }
